"""
Make sure the ``justext`` package living in this directory is the one that gets
imported by the test suite, even when another (possibly older) copy of jusText
is installed in ``site-packages``.
"""

from __future__ import absolute_import

import os
import sys


ROOT_DIRECTORY = os.path.dirname(os.path.abspath(__file__))
LOCAL_PACKAGE = os.path.join(ROOT_DIRECTORY, "justext", "__init__.py")

sys.path.insert(0, ROOT_DIRECTORY)

# drop an already imported jusText coming from somewhere else
_imported = sys.modules.get("justext")
if _imported is not None:
    _imported_file = os.path.abspath(getattr(_imported, "__file__", "") or "")
    if _imported_file != LOCAL_PACKAGE:
        for _name in [n for n in sys.modules if n == "justext" or n.startswith("justext.")]:
            del sys.modules[_name]
